-- Check if reg_compliance has entries not linked via trade_records
SELECT COUNT(*) FROM reg_compliance rc
WHERE NOT EXISTS (
    SELECT 1 FROM trade_records tr WHERE tr."REC_KEY" = rc."REC_COMP"
);

-- Find that one orphaned compliance record
SELECT rc."REC_COMP", rc."compliance_data" FROM reg_compliance rc
WHERE NOT EXISTS (
    SELECT 1 FROM trade_records tr WHERE tr."REC_KEY" = rc."REC_COMP"
);
